elAlt,\n\t\tTextColor3 = Theme.text,\n\t\tFont = Theme.boldFont,\n\t\tTextScaled = true,\n\t\tAutoButtonColor = true,\n\t}\n\tfor key, value in props do\n\t\tdefaults[key] = value\n\tend\n\tlocal list = children or {}\n\ttable.insert(list, corner(8))\n\treturn make(\"TextButton\", defaults, list)\nend\n\n-- Screen layout ---------------------------------------------------------------------\n\nlocal screen = make(\"ScreenGui\", {\n\tName = \"GuessAndDraw\",\n\tResetOnSpawn = false,\n\t-- Lay out in full-window pixels, the same space as GetMouseLocation(), so the\n\t-- pointer maps onto the canvas with no topbar offset.\n\tIgnoreGuiInset = true,\n\tZIndexBehavior = Enum.ZIndexBehavior.Sibling,\n\tParent = player:WaitForChild(\"PlayerGui\"),\n})\n\nlocal root = make(\"Frame\", {\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundColor3 = Theme.background,\n\tBorderSizePixel = 0,\n\tParent = screen,\n}, {\n\t-- Keep the panels clear of Roblox's topbar buttons.\n\tmake(\"UIPadding\", { PaddingTop = UDim.new(0, GuiService:GetGuiInset().Y) }),\n})\n\n-- Top bar: round, word, timer\nlocal topBar = make(\"Frame\", {\n\tPosition = UDim2.fromScale(0.01, 0.015),\n\tSize = UDim2.fromScale(0.98, 0.09),\n\tBackgroundColor3 = Theme.panel,\n\tParent = root,\n}, { corner(12), pad(6) })\n\nlocal roundLabel = label({\n\tSize = UDim2.fromScale(0.2, 1),\n\tText = \"\",\n\tFont = Theme.headingFont,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = topBar,\n}, { maxText(26) })\n\nlocal wordLabel = label({\n\tPosition = UDim2.fromScale(0.2, 0),\n\tSize = UDim2.fromScale(0.6, 1),\n\tText = \"\",\n\tFont = Theme.headingFont,\n\tParent = topBar,\n}, { maxText(36) })\n\nlocal timerLabel = label({\n\tAnchorPoint = Vector2.new(1, 0),\n\tPosition = UDim2.fromScale(1, 0),\n\tSize = UDim2.fromScale(0.2, 1),\n\tText = \"\",\n\tFont = Theme.headingFont,\n\tTextXAlignment = Enum.TextXAlignment.Right,\n\tParent = topBar,\n}, { maxText(32) })\n\n-- Left: players\nlocal playersPanel = make(\"Frame\", {\n\tPosition = UDim2.fromScale(0.01, 0.12),\n\tSize = UDim2.fromScale(0.18, 0.865),\n\tBackgroundColor3 = Theme.panel,\n\tParent = root,\n}, { corner(12), pad(8) })\n\nlocal playersList = make(\"ScrollingFrame\", {\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundTransparency = 1,\n\tBorderSizePixel = 0,\n\tScrollBarThickness = 4,\n\tCanvasSize = UDim2.new(),\n\tAutomaticCanvasSize = Enum.AutomaticSize.Y,\n\tParent = playersPanel,\n}, {\n\tmake(\"UIListLayout\", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }),\n})\n\n-- Centre: canvas and toolbar\nlocal centre = make(\"Frame\", {\n\tPosition = UDim2.fromScale(0.2, 0.12),\n\tSize = UDim2.fromScale(0.56, 0.865),\n\tBackgroundTransparency = 1,\n\tParent = root,\n})\n\nlocal canvasArea = make(\"Frame\", {\n\tSize = UDim2.fromScale(1, 0.83),\n\tBackgroundTransparency = 1,\n\tParent = centre,\n})\n\n-- A CanvasGroup clips rotated children, which a plain Frame with ClipsDescendants doesn't.\nlocal canvas = make(\"CanvasGroup\", {\n\tName = \"Canvas\",\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.5, 0.5),\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundColor3 = Config.BACKGROUND_COLOR,\n\tActive = true,\n\tParent = canvasArea,\n}, {\n\tmake(\"UIAspectRatioConstraint\", { AspectRatio = Config.CANVAS_ASPECT }),\n\tcorner(12),\n})\n\n-- Replaces the mouse pointer over the canvas: a dot the size and colour of the brush,\n-- centred exactly where the line will be drawn. It sits on its own layer so moving\n-- it doesn't make the CanvasGroup re-render every stroke.\nlocal cursorLayer = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.5, 0.5),\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundTransparency = 1,\n\tClipsDescendants = true,\n\tZIndex = 5,\n\tParent = canvasArea,\n}, {\n\tmake(\"UIAspectRatioConstraint\", { AspectRatio = Config.CANVAS_ASPECT }),\n})\n\nlocal cursorDot = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tBorderSizePixel = 0,\n\tVisible = false,\n\tParent = cursorLayer,\n}, {\n\tmake(\"UICorner\", { CornerRadius = UDim.new(0.5, 0) }),\n\tmake(\"UIStroke\", { Color = Color3.fromRGB(90, 90, 90), Thickness = 1 }),\n\tmake(\"UISizeConstraint\", { MinSize = Vector2.new(5, 5) }),\n})\n\nlocal renderer = CanvasRenderer.new(canvas)\n\n-- Overlay over the canvas for waiting / choosing / reveal / winners.\nlocal overlay = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.5, 0.5),\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundColor3 = Color3.fromRGB(20, 28, 60),\n\tBackgroundTransparency = 0.15,\n\tZIndex = 10,\n\tParent = canvasArea,\n}, {\n\tmake(\"UIAspectRatioConstraint\", { AspectRatio = Config.CANVAS_ASPECT }),\n\tcorner(12),\n\tpad(16),\n})\n\nlocal overlayTitle = label({\n\tSize = UDim2.fromScale(1, 0.2),\n\tPosition = UDim2.fromScale(0, 0.06),\n\tTextColor3 = Color3.new(1, 1, 1),\n\tFont = Theme.headingFont,\n\tZIndex = 11,\n\tParent = overlay,\n}, { maxText(44) })\n\nlocal overlaySubtitle = label({\n\tSize = UDim2.fromScale(1, 0.1),\n\tPosition = UDim2.fromScale(0, 0.27),\n\tTextColor3 = Color3.fromRGB(205, 215, 245),\n\tZIndex = 11,\n\tParent = overlay,\n}, { maxText(24) })\n\nlocal overlayBody = make(\"Frame\", {\n\tSize = UDim2.fromScale(1, 0.55),\n\tPosition = UDim2.fromScale(0, 0.42),\n\tBackgroundTransparency = 1,\n\tZIndex = 11,\n\tParent = overlay,\n})\n\n-- Below the canvas: drawing tools (drawer only) or a hint (guessers).\nlocal toolbar = make(\"Frame\", {\n\tPosition = UDim2.fromScale(0, 0.85),\n\tSize = UDim2.fromScale(1, 0.15),\n\tBackgroundColor3 = Theme.panel,\n\tVisible = false,\n\tParent = centre,\n}, {\n\tcorner(12),\n\tpad(6),\n\tmake(\"UIListLayout\", {\n\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\tPadding = UDim.new(0.015, 0),\n\t\tVerticalAlignment = Enum.VerticalAlignment.Center,\n\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t}),\n})\n\nlocal guessHint = label({\n\tPosition = UDim2.fromScale(0, 0.85),\